-- State transitions declared for SubscriptionPlan: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION subscription.subscription_plans_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('active', 'archived'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: subscription_plans.status % -> %', OLD."status", NEW."status"
            USING ERRCODE = 'check_violation', COLUMN = 'status', CONSTRAINT = 'tg_subscription_plans__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS subscription_plans_status_transition_check ON subscription.subscription_plans;
CREATE TRIGGER subscription_plans_status_transition_check
    BEFORE UPDATE OF "status" ON subscription.subscription_plans
    FOR EACH ROW EXECUTE FUNCTION subscription.subscription_plans_status_transition_check();
